        int eventCount = n * (n - 1) + n;
        long[] events = new long[eventCount];
        int index = 0;

        for (int u = 0; u < n; u++) {
            for (int v = 0; v < n; v++) {
                if (u == v) continue;
                long dx = (long) x[u] - x[v];
                long dy = (long) y[u] - y[v];
                long distanceSquared = dx * dx + dy * dy;
                int id = u * n + v;
                events[index++] = (distanceSquared << 32) | (id & 0xffffffffL);
            }

            long dx = x[u];
            long dy = y[u];
            long distanceSquared = dx * dx + dy * dy;
            int id = base + u;
            events[index++] = (distanceSquared << 32) | (id & 0xffffffffL);
        }

        Arrays.sort(events);

        int[] best = new int[n];
        int[] pending = new int[n];
        int[] touched = new int[n];
        int answer = 0;

        int end = events.length - 1;
        while (end >= 0) {
            long distanceSquared = events[end] >>> 32;
            int start = end;
            while (start >= 0 && (events[start] >>> 32) == distanceSquared) {
                start--;
            }

            int touchedCount = 0;
            for (int i = start + 1; i <= end; i++) {
                int id = (int) events[i];
                int from;
                int to;
                int value;

                if (id >= base) {
                    to = id - base;
                    value = 1;
                } else {
                    from = id / n;
                    to = id % n;
                    if (best[from] == 0) continue;
                    value = best[from] + 1;
                }

                if (value > answer) answer = value;
                if (pending[to] == 0) {
                    touched[touchedCount++] = to;
                    pending[to] = value;
                } else if (value > pending[to]) {
                    pending[to] = value;
                }
            }

            for (int i = 0; i < touchedCount; i++) {
                int v = touched[i];
                if (pending[v] > best[v]) best[v] = pending[v];
                pending[v] = 0;
            }

            end = start;
        }

        System.out.println(answer);
    }
}
